struct Marker{std::string tx,digest,state,helper,uninstaller;};
struct CopyIO{Bytes journal;std::optional<Bytes> receipt;std::map<std::string,Bytes> files;Bytes readJournal(){return journal;}std::optional<Bytes> readReceipt(){return receipt;}std::optional<Bytes> readOwned(const std::string& name){auto f=files.find(name);return f==files.end()?std::optional<Bytes>{}:f->second;}};
int wmain(int argc,wchar_t** argv){try{need(argc==2,"copied state directory");fs::path dir=argv[1];auto metadata=dir/L"metadata-LOCAL-ONLY";auto raw=load(metadata/L"management.bin");Reader r{raw};need(r.text()=="SonicLatch-management-v2","marker schema");Marker marker{r.text(),r.text(),r.text(),r.text(),r.text()};r.end();auto plan=decodePlan(load(metadata/L"transactions"/fs::path(marker.tx)/L"plan.bin"));CopyIO io;io.journal=load(metadata/L"transactions"/fs::path(marker.tx)/L"journal.bin");io.receipt=load(metadata/L"receipt.bin");for(const auto& row:plan.steps)io.files.emplace(row.path,load(dir/L"payload-LOCAL-ONLY"/fs::path(row.path).lexically_relative(L"SonicLatch")));std::optional<Bytes> helper=load(metadata/L"helper.exe"),uninstaller=load(metadata/L"Uninstall.exe");unsigned checks{};auto verify=[&]{need(copiedRegistration==registration(plan,L"C:\\ProgramData\\SonicLatch\\Installer"),"copied registered values differ");++checks;};unsigned cases{};
 for(int caller:{0,1}){(void)caller;need(registeredManagementComplete(io,plan,marker,helper,uninstaller,verify),"exact registered no-op");++cases;}need(checks==2,"registration verified on repeated no-op");
 auto changedMarker=marker;changedMarker.state="awaiting-uninstaller";need(!registeredManagementComplete(io,plan,changedMarker,helper,uninstaller,verify),"pending handoff must continue");++cases;changedMarker=marker;changedMarker.tx=std::string(32,'f');need(!registeredManagementComplete(io,plan,changedMarker,helper,uninstaller,verify),"different tx not no-op");++cases;
 const auto refuse=[&](auto action){bool stopped=false;try{action();}catch(...){stopped=true;}need(stopped,"modified completed evidence must stop");++cases;};
 changedMarker=marker;changedMarker.digest=std::string(64,'f');refuse([&]{registeredManagementComplete(io,plan,changedMarker,helper,uninstaller,verify);});need(checks==2,"same-tx digest rejection precedes registration or mutation");
 auto altered=io;altered.receipt="changed";refuse([&]{registeredManagementComplete(altered,plan,marker,helper,uninstaller,verify);});altered=io;altered.files.begin()->second="changed";refuse([&]{registeredManagementComplete(altered,plan,marker,helper,uninstaller,verify);});altered=io;altered.journal=encode(Journal{plan.transactionId,hashBytes(encode(plan)),State::Applying,0,0});refuse([&]{registeredManagementComplete(altered,plan,marker,helper,uninstaller,verify);});refuse([&]{registeredManagementComplete(io,plan,marker,std::optional<Bytes>{"changed"},uninstaller,verify);});refuse([&]{registeredManagementComplete(io,plan,marker,helper,{},verify);});refuse([&]{registeredManagementComplete(io,plan,marker,helper,uninstaller,[]{throw std::runtime_error("changed registration");});});
 std::cout<<"PASS "<<cases<<" copied registered-management cases: authenticated repeat is no-op; pending/new tx continues; changed receipt/payload/journal/helper/uninstaller/registration refused. IO exposes reads only; no self-helper replacement or slot replay. Caller identity deliberately irrelevant after recorded helper is authenticated. Native Setup/registry mutation NOT RUN.\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
